mapper.select:

SELECT #{push} AS time,area_id AS area,ip_addr AS IP,SUM(c2s_byte_len+s2c_byte_len) AS count
FROM traffic_ip_active_statistic
   WHERE stat_time >= #{start}
   AND stat_time < #{end}
GROUP BY IP ,area
ORDER BY count DESC
LIMIT 10;

SELECT entrance_id AS entrance
FROM ntc_device_info
GROUP BY entrance;
